    function testRegression_property() public {
        TokenMock token = new TokenMock();
        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);
        uint[] memory vals = new uint[](2);
        vals[0] = 100;
        vals[1] = 200;
        bool success;
        try c.transfer(address(this), address(token), tos, vals) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(token.callCount() == 2);
    }
}

contract TokenMock {
    uint public callCount;
    function transferFrom(address, address, uint) external returns (bool) {
